// writeEntryConfig writes the configuration the product is started with.
//
// The product no longer reads a second chat client: a conversation turn is
// generated by the learning Agent's chat model, the one [isolatedEntry]
// configures. The released product refuses a configuration file that still
// carries the retired [ordinaryChat] section - it refuses it by name, so the
// evaluation wrote a file the product could not start with, and every L4 v1
// attempt failed for that reason alone.
//
// The section is therefore not written. The ordinary path, if anything asks
// for it, now uses the same [isolatedEntry] client the evaluation already
// points at its loopback wire, so no request can leave the machine either.
func writeEntryConfig(path string, s *entry.Settings) error {
	envelope := struct {
		*config.Config
		Entry any `toml:"isolatedEntry"`
	}{s.Config, s.Entry}
	file, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
	if err != nil {
		return err
	}
	return errors.Join(toml.NewEncoder(file).Encode(envelope), file.Close())
}

// serveStandardProduct calls exactly the Run used by cmd/gopherlearn-integrated.
// It adds neither a custom product assembly nor alternate worker configuration.
type standardProduct struct {
	cancel  context.CancelFunc
	done    chan error
	stopped bool
}

func startStandardProduct(path string) *standardProduct {
	ctx, cancel := context.WithCancel(context.Background())
	p := &standardProduct{cancel: cancel, done: make(chan error, 1)}
	go func() { p.done <- hybrid.Run(ctx, path) }()
	return p
}
func (p *standardProduct) stop() error {
	if p.stopped {
		return nil
	}
	p.stopped = true
	p.cancel()
	select {
	case err := <-p.done:
		if err != nil {
			return fmt.Errorf("standard product entry failed")
		}
		return nil
	case <-time.After(35 * time.Second):
		return fmt.Errorf("standard product shutdown incomplete")
	}
}

func loginStandardProduct(ctx context.Context, p *standardProduct, client *http.Client, base, user, password string) (string, error) {
	body, _ := json.Marshal(map[string]string{"username": user, "password": password})
	for {
		select {
		case <-p.done:
			p.cancel()
			p.stopped = true
			return "", fmt.Errorf("standard product failed before readiness")
		default:
		}
		attempt, cancel := context.WithTimeout(ctx, time.Second)
		request, err := http.NewRequestWithContext(attempt, http.MethodPost, base+"/api/v1/user/login", bytes.NewReader(body))
		if err != nil {
			cancel()
			return "", err
		}
		request.Header.Set("Content-Type", "application/json")
		response, err := client.Do(request)
		var token string
		if err == nil {
			var result struct {
				Token string `json:"token"`
			}
			if response.StatusCode == 200 && json.NewDecoder(io.LimitReader(response.Body, 1<<20)).Decode(&result) == nil {
				token = result.Token
			}
			response.Body.Close()
		}
		cancel()
		if token != "" {
			return token, nil
		}
		select {
		case <-ctx.Done():
			return "", fmt.Errorf("standard product readiness timed out")
		case <-time.After(50 * time.Millisecond):
		}
	}
}

// askProductQuestion asks one question of the restored conversation.
//
// The questions of an attempt are asked in the same session, one after the
// other, so that a follow-up is answered in the context of the question
// before it. Every question keeps its own answer, its own raw response and
// its own identifier.
//
// The request id is the product's own idempotency key. An attempt that asks
// one question keeps the key it always used; an attempt that asks several
// gives each of them its own, because one key would make the second
// question a replay of the first.
func askProductQuestion(ctx context.Context, client *http.Client, base, token, sessionID string, question Question, requestID string, index int) (QuestionResult, error) {
	entry := QuestionResult{Index: index, Turn: question.Turn, Question: question.Text}
	if index > 0 {
		requestID = fmt.Sprintf("%s-%d", requestID, index+1)
	}
	body, _ := json.Marshal(map[string]any{"sessionId": sessionID, "requestId": requestID, "question": question.Text, "knowledgePolicy": "knowledge_preferred", "enableThinking": true})
	request, err := http.NewRequestWithContext(ctx, http.MethodPost, base+"/api/v1/AI/agent/run", bytes.NewReader(body))
	if err != nil {
		return entry, err
	}
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set("Authorization", "Bearer "+token)
	entry.StartedAt = time.Now().UTC()
	started := time.Now()
	response, requestErr := client.Do(request)
	if requestErr == nil {
		entry.Response, requestErr = io.ReadAll(io.LimitReader(response.Body, 4<<20+1))
		response.Body.Close()
		if len(entry.Response) > 4<<20 {
			requestErr = fmt.Errorf("product response exceeds limit")
			entry.Response = nil
		}
		if requestErr == nil && response.StatusCode != 200 {
			requestErr = fmt.Errorf("product HTTP status %d", response.StatusCode)
		}
		var envelope struct {
			Answer string `json:"answer"`
			RunID  string `json:"runId"`
		}
		if requestErr == nil {
			requestErr = json.Unmarshal(entry.Response, &envelope)
			entry.Answer = envelope.Answer
			entry.RunID = envelope.RunID
			if entry.Answer == "" {
				requestErr = fmt.Errorf("product response has no answer")
			}
		}
	}
	entry.QuestionMilliseconds = time.Since(started).Milliseconds()
	entry.FinishedAt = time.Now().UTC()
	if requestErr != nil {
		entry.Error = requestErr.Error()
		return entry, requestErr
	}
	return entry, nil
}

// askProductQuestions asks the questions of an attempt, in order, in the one
// session.
//
// The questions are asked one after the other and not one session per
// question: a follow-up is only a follow-up when the earlier question and
// its answer are still in the conversation. The first failure ends the
// attempt, because a later question asked without the earlier one would not
// be the question the scenario asks.
func askProductQuestions(ctx context.Context, client *http.Client, base, token, sessionID string, questions []Question, requestID string) ([]QuestionResult, error) {
	asked := make([]QuestionResult, 0, len(questions))
	for index, question := range questions {
		entry, err := askProductQuestion(ctx, client, base, token, sessionID, question, requestID, index)
		asked = append(asked, entry)
		if err != nil {
			return asked, err
		}
	}
	return asked, nil
}

// readAgentSteps reads the steps of the given runs back from the product's
// own table, so that the evidence of every question is kept with that
// question and not in one pile.
func (s *Sandbox) readAgentSteps(ctx context.Context, userID int64, questions []QuestionResult) error {
	runIDs := make([]string, 0, len(questions))
	for _, question := range questions {
		if question.RunID != "" {
			runIDs = append(runIDs, question.RunID)
		}
	}
	if len(runIDs) == 0 {
		return nil
	}
	var rows []model.AgentStep
	err := (guardedStore{s}).with(ctx, func(tx *gorm.DB) error {
		return tx.Where("user_id = ? AND run_id IN ?", userID, runIDs).Order("run_id ASC, sequence ASC").Find(&rows).Error
	})
	if err != nil {
		return err
	}
	byRun := map[string][]model.AgentStep{}
	for _, row := range rows {
		byRun[row.RunID] = append(byRun[row.RunID], row)
	}
	for i := range questions {
		questions[i].Steps = byRun[questions[i].RunID]
	}
	return nil
}

func runOfflineEntry(ctx context.Context, repository string, snapshot Snapshot, input AttemptInput) (result ProductResult, resultErr error) {
	result.Scope = ProductScope
	result.Environment = "fake"
	result.Entry = "gopherlearn-integrated:hybrid.Run"
	result.QuietWindowSeconds = 86400
	defer func() {
		if len(result.Response) > 0 && !json.Valid(result.Response) {
			result.ResponseText = string(result.Response)
			result.Response = nil
		}
		if resultErr != nil {
			result.BackgroundAudit.Valid = false
			result.BackgroundAudit.Reason = resultErr.Error()
			result.Error = resultErr.Error()
		}
	}()
	if err := ctx.Err(); err != nil {
		return result, err
	}
	questions := input.Questions
	if len(questions) == 0 {
		return result, fmt.Errorf("question required")
	}
	for _, question := range questions {
		if strings.TrimSpace(question.Text) == "" {
			return result, fmt.Errorf("question required")
		}
	}
	if err := snapshot.Validate(); err != nil {
		return result, err
	}
	dir, err := os.MkdirTemp("", "gl-standard-offline-")
	if err != nil {
		return result, err
	}
	defer os.RemoveAll(dir)
	settings, err := offlineSettings(repository, filepath.Join(dir, "knowledge"))
	if err != nil {
		return result, err
	}
	result.Provenance, err = collectProvenance(ctx, repository, settings, snapshot)
	if err != nil {
		return result, err
	}
	s, err := NewSandbox(ctx)
	if err != nil {
		return result, err
	}
	defer func() { resultErr = errors.Join(resultErr, closeSandbox(s)) }()
	if err = s.InitProductSchema(ctx); err != nil {
		return result, err
	}
	password, err := randomHex(24)
	if err != nil {
		return result, err
	}
	hash, err := utils.HashPassword(password)
	if err != nil {
		return result, err
	}
	if err = s.SeedProduct(ctx, model.User{ID: snapshot.Session.UserID, Username: snapshot.Session.UserName, Password: hash}, nil, settings.Config.StorageDir); err != nil {
		return result, err
	}
	// The seeded profile memories are written into the database the answer is
	// asked in, because that database is a fresh one and the restored
	// conversation does not carry the learner's profile with it.
	result.SeededMemories, result.SeededMemoryRows, err = seedAttemptMemories(ctx, s, snapshot.Session.UserID, input.Memories)
	if err != nil {
		return result, err
	}
	restoreStart := time.Now()
	if err = s.Restore(ctx, snapshot); err != nil {
		return result, err
	}
	result.RestoreMilliseconds = time.Since(restoreStart).Milliseconds()
	journal, err := s.StartJobJournal(ctx)
	if err != nil {
		return result, err
	}
	redis, err := newRedisSandbox(ctx)
	if err != nil {
		return result, err
	}
	defer func() {
		cleanup, cancel := context.WithTimeout(context.Background(), 15*time.Second)
		defer cancel()
		resultErr = errors.Join(resultErr, redis.Close(cleanup))
	}()
	ledger := &ModelLedger{}
	roles, err := LoadRolePrompts(repository, memoryrecall.ReadMode(settings.Config.MemoryReadMode))
	if err != nil {
		return result, err
	}
	stub := &offlineChat{}
	wire := offlineWire(ledger, roles, stub)
	defer wire.Close()
	connection, err := s.ConnectionInfo(ctx)
	if err != nil {
		return result, err
	}
	settings.Config.MysqlHost = connection.Host
	settings.Config.MysqlPort, err = strconv.Atoi(connection.Port)
	if err != nil {
		return result, err
	}
	settings.Config.MysqlDatabaseName = connection.Database
	settings.Config.MysqlUser = connection.User
	settings.Config.MysqlPassword = connection.Password
	settings.Config.RedisHost, connection.Port, err = net.SplitHostPort(redis.addr)
	if err != nil {
		return result, err
	}
	settings.Config.RedisPort, err = strconv.Atoi(connection.Port)
	if err != nil {
		return result, err
	}
	settings.Entry.ChatBaseURL = wire.URL + "/v1"
	settings.Config.RagRerankEndpoint = wire.URL + "/v1/rerank"
	settings.Config.RagEmbeddingBaseURL = wire.URL + "/v1"
	settings.Config.JwtConfig.Key, err = randomHex(32)
	if err != nil {
		return result, err
	}
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		return result, err
	}
	address := listener.Addr().(*net.TCPAddr)
	settings.Config.MainConfig.Host = "127.0.0.1"
	settings.Config.MainConfig.Port = address.Port
	listener.Close()
	path := filepath.Join(dir, "product.toml")
	// The existing configuration intentionally reads this one credential only
	// from the process environment. Use a fake token for the loopback service.
	oldToken, hadToken := os.LookupEnv("RAG_RERANK_AUTH_TOKEN")
	if err = os.Setenv("RAG_RERANK_AUTH_TOKEN", settings.Config.RagRerankToken); err != nil {
		return result, err
	}
	defer func() {
		if hadToken {
			os.Setenv("RAG_RERANK_AUTH_TOKEN", oldToken)
		} else {
			os.Unsetenv("RAG_RERANK_AUTH_TOKEN")
		}
	}()
	if err = writeEntryConfig(path, settings); err != nil {
		return result, err
	}
	// Verify serialized settings before reaching any production resource factory.
	loaded, err := entry.Load(path)
	if err != nil {
		return result, err
	}
	if loaded.Config.EpisodeQuietWindowSeconds != 86400 || loaded.Entry.Migrate || !loaded.Config.RagRerankEnabled || loaded.Config.RagRerankEndpoint != wire.URL+"/v1/rerank" {
		return result, fmt.Errorf("unexpected standard entry settings")
	}
	result.Audit.Started = time.Now().UTC()
	product := startStandardProduct(path)
	defer func() { resultErr = errors.Join(resultErr, product.stop()) }()
	client := &http.Client{Timeout: time.Minute, Transport: &http.Transport{Proxy: nil}, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
	defer client.CloseIdleConnections()
	base := "http://" + settings.Address()
	token, err := loginStandardProduct(ctx, product, client, base, snapshot.Session.UserName, password)
	if err != nil {
		return result, err
	}
	result.Audit.Before, result.BeforeCounts, err = s.ObserveJobs(ctx)
	if err != nil {
		return result, err
	}
	asked, requestErr := askProductQuestions(ctx, client, base, token, snapshot.Session.ID, questions, "offline-final-question")
	result.Answer = asked[0].Answer
	result.Response = asked[0].Response
	result.Questions = asked
	if err := s.readAgentSteps(ctx, snapshot.Session.UserID, asked); err != nil {
		resultErr = errors.Join(resultErr, err)
	}
	result.Audit.Answered = time.Now().UTC()
	result.QuestionMilliseconds = asked[len(asked)-1].FinishedAt.Sub(asked[0].StartedAt).Milliseconds()
	collect, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	barrierErr := journal.AnswerBarrier(collect)
	result.Audit.After, result.AfterCounts, err = s.ObserveJobs(collect)
	stopErr := product.stop()
	result.ShutdownComplete = stopErr == nil
	wire.Close()
	var stoppedErr error
	_, result.StoppedCounts, stoppedErr = s.ObserveJobs(collect)
	result.Events, result.Audit.ExecutedBeforeAnswer, resultErr = journal.Finish(collect)
	result.Calls = BindRuns(AttributeCalls(ledger.Calls(), result.Audit.Answered), snapshot.Session.ID, asked)
	var usageErr error
	result.UsageByRole, usageErr = SummarizeCalls(result.Calls)
	result.ContextMessages = stub.answerInput()
	// The context of every question is kept with that question, so that a
	// reader can see what the later question was answered against.
	inputs := stub.answerInputs()
	for index := range result.Questions {
		if index < len(inputs) {
			result.Questions[index].ContextMessages = inputs[index]
		}
	}
	for _, c := range result.Calls {
		result.Audit.Calls = append(result.Audit.Calls, BackgroundCall{Role: c.Role, Started: c.Started})
	}
	result.Audit.Complete = resultErr == nil && barrierErr == nil && stopErr == nil && stoppedErr == nil && err == nil && usageErr == nil && ledger.Complete()
	resultErr = errors.Join(resultErr, requestErr, barrierErr, err, stopErr, stoppedErr, usageErr, result.Audit.ValidateBackground())
	result.BackgroundAudit.Valid = resultErr == nil
	return result, resultErr
}
